GET COLLECTION biologici;
SAVE AS temp_bio@jcoql_test;
GET COLLECTION scontati;
SAVE AS temp_scontati@jcoql_test;
MERGE COLLECTIONS temp_bio@jcoql_test, temp_scontati@jcoql_test REMOVE DUPLICATES;

GET COLLECTION biologici;
SAVE AS temp_bio@jcoql_test;
GET COLLECTION scontati;
SAVE AS temp_scontati@jcoql_test;
MERGE COLLECTIONS temp_bio@jcoql_test, temp_scontati@jcoql_test REMOVE DUPLICATES;

GET COLLECTION biologici;
SAVE AS temp_bio@jcoql_test;
GET COLLECTION scontati;
SAVE AS temp_scontati@jcoql_test;
MERGE COLLECTIONS temp_bio@jcoql_test, temp_scontati@jcoql_test REMOVE DUPLICATES;

GET COLLECTION biologici;
FILTER CASE WHERE .organic = TRUE;
SAVE AS sottoinsieme1@jcoql_test;
GET COLLECTION scontati;
FILTER CASE WHERE .discount > 0;
SAVE AS sottoinsieme2@jcoql_test;
MERGE COLLECTIONS sottoinsieme1@jcoql_test, sottoinsieme2@jcoql_test;

GET COLLECTION products;
EXPAND UNPACK TRUE ARRAY .reviews TO .elemento;
FILTER CASE WHERE .elemento.item.rating > 4;

GET COLLECTION products;
EXPAND UNPACK TRUE ARRAY .reviews TO .review;
FILTER CASE WHERE .review.item.rating = 5;

GET COLLECTION products;
EXPAND UNPACK TRUE ARRAY .reviews TO .elemento;
FILTER CASE WHERE .elemento.item.rating < 3;

GET COLLECTION products;
FILTER CASE WHERE .organic = TRUE;
EXPAND UNPACK TRUE ARRAY .reviews TO .elemento;
FILTER GENERATE BUILD { .reviews: .elemento.item };

GET COLLECTION products;
FILTER CASE WHERE .organic = TRUE;
GROUP PARTITION TRUE BY .category INTO .prodotti_bio_per_categoria;

GET COLLECTION products;
GROUP PARTITION .organic = TRUE BY .organic INTO .biologici
PARTITION .organic = FALSE BY .organic INTO .non_biologici;

GET COLLECTION products;
FILTER CASE WHERE .rating >= 4.0;
SAVE AS sottoinsieme1@jcoql_test;
GET COLLECTION products;
FILTER CASE WHERE .discount > 30;
SAVE AS sottoinsieme2@jcoql_test;
MERGE COLLECTIONS sottoinsieme1@jcoql_test, sottoinsieme2@jcoql_test REMOVE DUPLICATES;

GET COLLECTION biologici;
SAVE AS temp_bio@jcoql_test;
GET COLLECTION products;
FILTER CASE WHERE .discount = 0;
SAVE AS temp_no_discount@jcoql_test;
MERGE COLLECTIONS temp_bio@jcoql_test, temp_no_discount@jcoql_test;

GET COLLECTION orders;
FILTER CASE WHERE .total > 100;
SAVE AS sottoinsieme1@jcoql_test;
GET COLLECTION orders;
FILTER CASE WHERE .total < 20;
SAVE AS sottoinsieme2@jcoql_test;
MERGE COLLECTIONS sottoinsieme1@jcoql_test, sottoinsieme2@jcoql_test REMOVE DUPLICATES;

GET COLLECTION orders;
EXPAND UNPACK TRUE ARRAY .items TO .item;
FILTER CASE WHERE .item.item.product_id = 'prod_001';

GET COLLECTION products;
GROUP PARTITION .organic = TRUE BY .category INTO .biologici
PARTITION .organic = FALSE BY .category INTO .non_biologici;

USE DB jcoql_test ON DEFAULT SERVER;
GET COLLECTION products;
FILTER CASE WHERE .organic = TRUE;

GET COLLECTION products;
EXPAND UNPACK TRUE ARRAY .reviews TO .review;
FILTER CASE WHERE .review.item.rating = 5;

GET COLLECTION products;
FILTER CASE WHERE .organic = TRUE;
EXPAND UNPACK TRUE ARRAY .reviews TO .review;

GET COLLECTION orders;
EXPAND UNPACK TRUE ARRAY .items TO .item;
SAVE AS chaintemp1@jcoql_test;
GET COLLECTION chaintemp1;
JOIN OF COLLECTIONS chaintemp1@jcoql_test AS c, products@jcoql_test AS p CASE WHERE .c.item.item.product_id = .p._id;

GET COLLECTION biologici;
FILTER CASE WHERE .organic = TRUE;
GROUP PARTITION TRUE BY .category INTO .risultato;

GET COLLECTION products;
GROUP PARTITION .organic = TRUE BY .organic INTO .biologici
PARTITION .organic = FALSE BY .organic INTO .nonBiologici;

GET COLLECTION products;
FILTER CASE WHERE .rating >= 4;
SAVE AS sottoinsieme1@jcoql_test;
GET COLLECTION products;
FILTER CASE WHERE .discount > 30;
SAVE AS sottoinsieme2@jcoql_test;
MERGE COLLECTIONS sottoinsieme1@jcoql_test, sottoinsieme2@jcoql_test REMOVE DUPLICATES;

GET COLLECTION products; FILTER CASE WHERE .organic = TRUE; SAVE AS biologici@jcoql_test;
GET COLLECTION products; FILTER CASE WHERE .discount = 0; SAVE AS senza_sconto@jcoql_test;
MERGE COLLECTIONS biologici@jcoql_test, senza_sconto@jcoql_test REMOVE DUPLICATES;
